package com.rikkeibank.transaction.aop; import org.aspectj.lang.JoinPoint; import org.aspectj.lang.annotation.*; import org.slf4j.*; import org.springframework.stereotype.Component;
@Aspect @Component public class ServiceLoggingAspect {private static final Logger log=LoggerFactory.getLogger(ServiceLoggingAspect.class);@AfterThrowing(pointcut="execution(* com.rikkeibank.transaction.service..*(..))",throwing="ex") public void error(JoinPoint jp,Throwable ex){log.error("Service error at {}: {}",jp.getSignature().toShortString(),ex.getMessage(),ex);}}
